            resolved = (status == "RESOLVED") || (status == "SETTLED");
        }
        return new Dictionary<string, object>() {
            { "id", slug },
            { "slug", slug },
            { "event", ((slug != null)) ? this.shortenSlug(slug) : null },
            { "title", title },
            { "description", this.safeString(rawTopic, "description") },
            { "markets", marketsList },
            { "active", active },
            { "url", null },
            { "image", this.safeString(rawTopic, "imageUrl") },
            { "created", this.parse8601(created) },
            { "createdDatetime", created },
            { "end", this.parse8601(endDate) },
            { "endDatetime", endDate },
            { "category", this.safeString(rawTopic, "marketVariant") },
            { "resolved", resolved },
            { "info", rawTopic },
        };
    }

    /**
     * @ignore
     * @method
     * @name predictfun#stripPriceFormatting
     * @description drops the formatting the venue puts in a price but not in its slug - the currency sign, and a comma that sits between two digits
     * @param {string} [text] the raw title or outcome label
     * @returns {string} the same text with '$' removed and thousands separators closed up
     */
    public virtual object stripPriceFormatting(object text)
    {
        if ((text == null))
        {
            return null;
        }
        string digits = "0123456789";
        List<object> chars = this.stringToCharsArray(text);
        int charsLength = (chars?.Count ?? 0);
        string stripped = "";
        for (object i = 0; isLessThan(i, charsLength); postFixIncrement(ref i))
        {
            string? ch = ((string)getValue(chars, i));
            bool keep = true;
            if (ch == "$")
            {
                keep = false;
            } else if (ch == ",")
            {
                // only a comma between two digits is a thousands separator: "1,500" has to close
                // up to "1500" to match the venue's comma-free slug. a comma anywhere else is
                // ordinary punctuation and stays, so it still separates words
                bool prevIsDigit = (isGreaterThan(i, 0)) && (digits.IndexOf(((string)getValue(chars, subtract(i, 1))), StringComparison.Ordinal) >= 0);
                bool nextIsDigit = (isLessThan((add(i, 1)), charsLength)) && (digits.IndexOf(((string)getValue(chars, add(i, 1))), StringComparison.Ordinal) >= 0);
                keep = !(prevIsDigit && nextIsDigit);
            }
            if (keep)
            {
                stripped = (stripped + ch);
            }
        }
        return stripped;
    }

    /**
     * @ignore
     * @method
     * @name predictfun#titleForMarketSymbol
     * @description decides what of a market title belongs in the unified symbol, given how many markets its topic holds
     * @param {string} [topicSlug] the slug of the enclosing topic
     * @param {string} [title] the market title
     * @param {int} [marketCount] how many markets the topic carries
     * @returns {string} the title to append, or the slug itself when the topic holds a single market
     */
    public virtual object titleForMarketSymbol(object topicSlug, object title, object marketCount = null)
    {
        // a topic holding one market needs nothing to tell its markets apart, and the title there
        // only restates the slug in another spelling - the venue writes the same window as
        // btc-updown-5m-1789017900 and as "Bitcoin Up or Down - September 10, 1:25AM-1:30AM ET".
        // returning the slug makes slugToMarketSymbol collapse the two halves into one part.
        // inside a multi-market topic the title is what keeps the handles apart, so it stays
        if ((isEqual(marketCount, 1)) && ((topicSlug != null)))
        {
            return topicSlug;
        }
        return this.stripPriceFormatting(title);
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parseTopicMarket
     * @description parses one nested market of a market topic into the unified market shape, building its outcome tokens
     * @param {object} rawMarket the nested market object
     * @param {object} rawTopic the enclosing raw market topic (carries slug/vendor/fees/dates)
     * @returns {object} a market structure
     */
    public virtual Dictionary<string, object> parseTopicMarket(object rawMarket, object rawTopic)
    {
        //
        //     {
        //         "boostEndsAt": "2026-08-27T14:15:00.000Z",
        //         "boostStartsAt": "2026-08-27T14:00:00.000Z",
        //         "categorySlug": "eth-updown-15m-1787839200",
        //         "conditionId": "0xa8e9c348c299989329debd86aaef81a1c4880d42c3954a684bdc731f7a113487",
        //         "createdAt": "2026-08-26T14:00:02.000Z",
        //         "decimalPrecision": 2,
        //         "description": "This market will resolve to \"Up\" if the ETH/USDT price at the end of the time range specified in the title is greater than the price at the beginning of that range.\r\n\r\nIt will resolve to \"Down\" if the ETH/USDT price at the end of the time range is lower than the price at the beginning of that range.\r\n\r\nIf the two prices are exactly equal, the market will resolve 50-50.\r\n\r\nThe primary resolution source for this market is Chainlink, specifically the ETH/USDT data stream available at https://data.chain.link/streams/eth-usdt-topofbook-datalink?timeframe=1d&chart=candlestick.\r\n\r\nTo verify the final price, use the close price of the 5m candlestick just before the market's end time. For example, for a market running from 1:00 to 1:15 PM ET or 1:10 to 1:15 PM ET, use the close price of the 1:10 PM candlestick as the final price.\r\n\r\nThe Chainlink stream uses the mid-price, which is calculated as the average price between the bid and ask prices from Binance's Top of Book, converted into the quote currency.\r\n\r\nThis market is based solely on the price reported by the Chainlink ETH/USDT data stream, not on other sources or spot markets.\r\n\r\nIf Chainlink data is unavailable or otherwise unusable for resolution, the market will resolve based on a consensus of reliable sources.",
        //         "feeRateBps": 200,
        //         "id": 1739803,
        //         "imageUrl": "https://static.predict.fun/automarket-eth-usd-15-minutes",
        //         "isBoosted": false,
        //         "isNegRisk": false,
        //         "isVisible": true,
        //         "isYieldBearing": false,
        //         "kalshiMarketTicker": null,
        //         "marketType": null,
        //         "marketVariant": "CRYPTO_UP_DOWN",
        //         "oracleQuestionId": "0x6ab55f25f108508e7c6cc9bb22e3304d3fcecd0771d741fdf6d67e6b7ab9af2c",
        //         "outcomes": [
        //             {
        //                 "bestAsk": {
        //                     "price": 0.98,
        //                     "size": 100
        //                 },
        //                 "bestBid": {
        //                     "price": 0.02,
        //                     "size": 100
        //                 },
        //                 "indexSet": 1,
        //                 "name": "Up",
        //                 "onChainId": "63015212288887519605689521802215931005858239156918107575780791658588345185817",
        //                 "status": null,
        //                 "team": null,
        //                 "variantData": null
        //             },
        //             {
        //                 "bestAsk": {
        //                     "price": 0.98,
        //                     "size": 100
        //                 },
        //                 "bestBid": {
        //                     "price": 0.02,
        //                     "size": 100
        //                 },
        //                 "indexSet": 2,
        //                 "name": "Down",
        //                 "onChainId": "111913554301217491431600756326792444318464112865057816486042507140136158411642",
        //                 "status": null,
        //                 "team": null,
        //                 "variantData": null
        //             }
        //         ],
        //         "polymarketConditionIds": [],
        //         "question": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
        //         "questionIndex": null,
        //         "resolution": null,
        //         "resolverAddress": "0x77620FAb2969dF2D5696F1f081940E416Cf17cA5",
        //         "rewards": {
        //             "current": null,
        //             "schedule": [
        //                 {
        //                     "endsAt": "2026-08-27T14:15:00.000Z",
        //                     "hourlyRate": 3000,
        //                     "startsAt": "2026-08-27T14:00:00.000Z"
        //                 }
        //             ]
        //         },
        //         "shareThreshold": 100,
        //         "spreadThreshold": 0.06,
        //         "status": "REGISTERED",
        //         "team": null,
        //         "title": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
        //         "tradingStatus": "OPEN",
        //         "variantData": {
        //             "endPrice": null,
        //             "priceFeedId": "0x0003543336278a459ac24c2f239ffa36f279cadc71f4babc9f8126c6ff10011d",
        //             "priceFeedProvider": "CHAINLINK",
        //             "priceFeedSymbol": "ETHUSDT",
        //             "startPrice": null,
        //             "type": "CRYPTO_UP_DOWN"
        //         }
        //     }
        //
        string? marketId = this.safeString(rawMarket, "id");
        string? topicSlug = this.safeString(rawMarket, "categorySlug");
        // the same handle parseEvent () derives for the enclosing event - stamping it here is what
        // lets every outcome-addressed structure (order, ticker, trade, position) report an event
        string? eventHandle = null;
        if ((topicSlug != null))
        {
            eventHandle = this.shortenSlug(topicSlug);
        }
        string? title = this.safeString(rawMarket, "title", marketId);
        List<object> topicMarkets = this.safeList(rawTopic, "markets", new List<object>() {});
        int marketCount = topicMarkets.Count;
        object symbolTitle = this.titleForMarketSymbol(topicSlug, title, marketCount);
        object marketSymbol = this.slugToMarketSymbol(topicSlug, symbolTitle);
        string? tradingStatus = this.safeString(rawMarket, "tradingStatus");
        string? status = this.safeString(rawMarket, "status");
        bool active = (tradingStatus == "OPEN");
        if ((tradingStatus == null))
        {
            active = (status == "REGISTERED") || (status == "OPEN");
        }
        bool resolved = (status == "RESOLVED") || (status == "SETTLED");
        string? endDate = this.safeString(rawTopic, "endsAt");
        string? feeRateBps = this.safeString(rawMarket, "feeRateBps", "200"); // todo check
        double? feeRate = this.parseNumber(Precise.stringDiv(feeRateBps, "10000"));
        string? decimalPrecision = this.safeString(rawMarket, "decimalPrecision", "2");
        double? pricePrecision = this.parseNumber(this.parsePrecision(decimalPrecision));
        Dictionary<string, object> precision = new Dictionary<string, object>() {
            { "amount", 0.01 },
            { "price", pricePrecision },
        };
        IList<object> rawOutcomes = (IList<object>)(this.safeList(rawMarket, "outcomes", new List<object>() {}));
        List<object> outcomes = new List<object>() {};
        string? resolvedOutcomeRaw = null;
        int rawOutcomesLength = (rawOutcomes?.Count ?? 0);
        for (int oi = 0; oi < rawOutcomesLength; oi++)
        {
            object rawOutcome = getValue(rawOutcomes, oi);
            // a label can carry a formatted price ("$1,800+"), and it goes into the outcome
            // handle verbatim - strip the same formatting the title gets
            string? rawLabel = this.safeStringUpper(rawOutcome, "name");
            string? label = ((string)this.stripPriceFormatting(rawLabel));
            string? tokenId = this.safeString(rawOutcome, "onChainId");
            string? outcomeHandle = ((string)add(add(marketSymbol, ":"), label));
            bool? winner = null;
            string? outcomeStatus = this.safeString(rawOutcome, "status");
            int? settleFractionRaw = null;
            if ((outcomeStatus != null))
            {
                winner = (outcomeStatus == "WON");
                if ((winner == true))
                {
                    settleFractionRaw = 1;
                    resolvedOutcomeRaw = outcomeHandle;
                } else
                {
                    settleFractionRaw = 0; // todo check
                }
            }
            int? settleFraction = settleFractionRaw;
            outcomes.Add(new Dictionary<string, object>() {
                { "id", tokenId },
                { "outcomeId", tokenId },
                { "outcome", outcomeHandle },
                { "market", marketSymbol },
                { "event", eventHandle },
                { "label", label },
                { "price", null },
                { "active", active },
                { "winner", winner },
                { "settleFraction", settleFraction },
                { "precision", precision },
                { "info", this.extend(new Dictionary<string, object>() {
                    { "marketId", marketId },
                }, rawOutcome) },
            });
        }
        string? resolvedOutcome = resolvedOutcomeRaw;
        string collateral = "USDT";
        string marketType = "binary";
        if (rawOutcomesLength > 2)
        {
            marketType = "categorical";
        }
        string? createdDatetime = this.safeString(rawMarket, "createdAt");
        return ((Dictionary<string, object>)((object)(new Dictionary<string, object>() {
            { "id", marketId },
            { "market", marketSymbol },
            { "base", collateral },
            { "quote", collateral },
            { "settle", null },
            { "baseId", marketId },
            { "quoteId", collateral },
            { "settleId", null },
            { "type", "prediction" },
            { "marketType", marketType },
            { "executionModel", "clob" },
            { "collateral", collateral },
            { "spot", false },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "prediction", true },
            { "active", active },
            { "resolved", resolved },
            { "resolvedOutcome", resolvedOutcome },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", this.parse8601(endDate) },
            { "expiryDatetime", endDate },
            { "strike", null },
            { "optionType", null },
            { "taker", feeRate },
            { "maker", 0 },
            { "percentage", true },
            { "tierBased", false },
            { "feeSide", "get" },
            { "precision", precision },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", 1 },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", 0.01 },
                    { "max", 0.99 },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", null },
                } },
            } },
            { "outcomes", outcomes },
            { "info", rawMarket },
            { "created", this.parse8601(createdDatetime) },
        })));
    }

    /**
     * @method
     * @name predictfun#fetchOrderBook
     * @description fetches the order book for a single prediction outcome token
     * @see https://dev.predict.fun/get-the-orderbook-for-a-market-25326908e0
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {int} [limit] not used by predictfun fetchOrderBook
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a prediction [order book structure](https://docs.ccxt.com/#/?id=order-book-structure)
     */
    public async override Task<ccxt.PredictionOrderBook> FetchOrderBook(string outcome, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", this.safeString(info, "marketId") },
        };
        Dictionary<string, object> response = await this.predictfunGetV1MarketsIdOrderbook(this.extend(request, parameters));
        //
        //     {
        //         "data":
        //             {
        //             "asks": [
        //                 [ 0.99, 101 ]
        //             ],
        //             "bids": [
        //                 [ 0.01, 101 ]
        //             ],
        //             "lastOrderSettled": null,
        //             "marketId": 1743016,
        //             "updateTimestampMs": 1787770521244
        //         },
        //         "success":true
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        Int64? timestamp = this.safeInteger(data, "updateTimestampMs");
        // The outcome lables are not the same as the outcome indexSet values, so we need to check the indexSet to determine which outcome is being requested
        Int64? indexSet = this.safeInteger(info, "indexSet");
        bool isYesOutcome = ((indexSet == 1));
        string? outcomeSymbol = this.safeOutcomeSymbol(outcome, outcomeObj);
        // the book endpoint is quoted in the yes token, the no side mirrors at 1 - price with bids and asks swapped
        if (isYesOutcome)
        {
            Dictionary<string, object> yesOrderbook = this.parseOrderBook(data, outcomeSymbol, timestamp, "bids", "asks", 0, 1);
            return ccxt.BaseExchange.ToPredictionOrderBook(this.safePredictionOrderBook(yesOrderbook, outcomeObj));
        } else
        {
            List<object> bids = this.safeList(data, "bids", new List<object>() {});
            List<object> asks = this.safeList(data, "asks", new List<object>() {});
            List<object> noBids = new List<object>() {};
            List<object> noAsks = new List<object>() {};
            for (int i = 0; i < bids.Count; i++)
            {
                List<object> bid = this.safeList(bids, i);
                string? bidPrice = this.safeString(bid, 0);
                double? bidSize = this.parseNumber(this.safeString(bid, 1));
                double? complementPrice = this.parseNumber(Precise.stringSub("1", bidPrice));
                noAsks.Add(new List<object>() {complementPrice, bidSize});
            }
            for (int i = 0; i < asks.Count; i++)
            {
                List<object> ask = this.safeList(asks, i);
                string? askPrice = this.safeString(ask, 0);
                double? askSize = this.parseNumber(this.safeString(ask, 1));
                double? complementPrice = this.parseNumber(Precise.stringSub("1", askPrice));
                noBids.Add(new List<object>() {complementPrice, askSize});
            }
            Dictionary<string, object> noOrderbook = new Dictionary<string, object>() {
                { "bids", this.sortBy(noBids, 0, true) },
                { "asks", this.sortBy(noAsks, 0) },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
                { "nonce", null },
            };
            return ccxt.BaseExchange.ToPredictionOrderBook(this.safePredictionOrderBook(noOrderbook, outcomeObj));
        }
    }

    /**
     * @method
     * @name predictfun#fetchTicker
     * @description fetches the best bid and ask for a single prediction outcome token
     * @see https://dev.predict.fun/get-market-by-id-25552989e0
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
     */
    public async override Task<ccxt.PredictionTicker> FetchTicker(string outcome, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "id", this.safeString(info, "marketId") },
        };
        // the market detail carries a bestBid/bestAsk per outcome, already sided for the NO
        // outcome - last price and volume live behind /last-sale and /stats, one request each,
        // so they are left undefined rather than spending extra calls on them
        Dictionary<string, object> response = await this.predictfunGetV1MarketsId(this.extend(request, parameters));
        //
        //     {
        //         "data": {
        //             "id": 2107,
        //             "title": "Will Trump acquire Greenland before 2027?",
        //             "tradingStatus": "OPEN",
        //             "status": "REGISTERED",
        //             "decimalPrecision": 2,
        //             "feeRateBps": 200,
        //             "outcomes": [
        //                 {
        //                     "name": "Yes",
        //                     "indexSet": 1,
        //                     "onChainId": "43765171147442247918432418752066697760469767620931280624762484655579631167373",
        //                     "bestBid": { "price": 0.02, "size": 1448.4122448979592 },
        //                     "bestAsk": { "price": 0.032, "size": 675.29 },
        //                     "status": null
        //                 },
        //                 {
        //                     "name": "No",
        //                     "indexSet": 2,
        //                     "bestBid": { "price": 0.968, "size": 675.29 },
        //                     "bestAsk": { "price": 0.98, "size": 1448.4122448979592 },
        //                     "status": null
        //                 }
        //             ]
        //         },
        //         "success": true
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        return ccxt.BaseExchange.ToPredictionTicker(this.parsePredictionTicker(data, outcomeObj));
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parsePredictionTicker
     * @description parses a raw market detail into a unified prediction ticker for one of its outcomes
     * @param {object} ticker the raw market object, with a nested outcomes list
     * @param {object} [market] the outcome the ticker belongs to
     * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
     */
    public override Dictionary<string, object> parsePredictionTicker(object ticker, object market = null)
    {
        //
        //     {
        //         "id": 2107,
        //         "title": "Will Trump acquire Greenland before 2027?",
        //         "tradingStatus": "OPEN",
        //         "status": "REGISTERED",
        //         "decimalPrecision": 2,
        //         "feeRateBps": 200,
        //         "outcomes": [
        //             {
        //                 "name": "Yes",
        //                 "indexSet": 1,
        //                 "onChainId": "43765171147442247918432418752066697760469767620931280624762484655579631167373",
        //                 "bestBid": { "price": 0.02, "size": 1448.4122448979592 },
        //                 "bestAsk": { "price": 0.032, "size": 675.29 },
        //                 "status": null
        //             },
        //             {
        //                 "name": "No",
        //                 "indexSet": 2,
        //                 "bestBid": { "price": 0.968, "size": 675.29 },
        //                 "bestAsk": { "price": 0.98, "size": 1448.4122448979592 },
        //                 "status": null
        //             }
        //         ]
        //     }
        //
        IDictionary<string, object> info = this.safeDict(market, "info", new Dictionary<string, object>() {});
        Int64? indexSet = this.safeInteger(info, "indexSet");
        List<object> rawOutcomes = this.safeList(ticker, "outcomes", new List<object>() {});
        int rawOutcomesLength = rawOutcomes.Count;
        object rawOutcome = new Dictionary<string, object>() {};
        bool outcomeFound = false;
        for (int i = 0; i < rawOutcomesLength; i++)
        {
            object candidate = getValue(rawOutcomes, i);
            if ((this.safeInteger(candidate, "indexSet") == indexSet))
            {
                rawOutcome = candidate;
                outcomeFound = true;
                break;
            }
        }
        if (!outcomeFound)
        {
            // an unmatched indexSet would otherwise return a ticker whose every quote is
            // undefined, which reads as an empty book rather than as a market that never
            // carried this outcome
            string? requested = this.safeOutcomeSymbol(null, market);
            throw new BadSymbol ((((this.id + " fetchTicker() did not find ") + requested) + " among the outcomes of its market")) ;
        }
        // the venue quotes each outcome on its own side of the book, so no complement is needed
        IDictionary<string, object> bestBid = this.safeDict(rawOutcome, "bestBid", new Dictionary<string, object>() {});
        IDictionary<string, object> bestAsk = this.safeDict(rawOutcome, "bestAsk", new Dictionary<string, object>() {});
        return this.safePredictionTicker(new Dictionary<string, object>() {
            { "outcome", this.safeOutcomeSymbol(null, market) },
            { "outcomeId", this.safeString(market, "outcomeId") },
            { "label", this.safeString(market, "label") },
            { "market", this.safeString(market, "market") },
            { "event", this.safeString(market, "event") },
            { "timestamp", null },
            { "datetime", null },
            { "high", null },
            { "low", null },
            { "bid", this.safeNumber(bestBid, "price") },
            { "bidVolume", this.safeNumber(bestBid, "size") },
            { "ask", this.safeNumber(bestAsk, "price") },
            { "askVolume", this.safeNumber(bestAsk, "size") },
            { "open", null },
            { "close", null },
            { "last", null },
            { "change", null },
            { "percentage", null },
            { "average", null },
            { "baseVolume", null },
            { "quoteVolume", null },
            { "info", ticker },
        });
    }

    /**
     * @method
     * @name predictfun#fetchMyTrades
     * @description fetches the settled matches the wallet took part in, on either side of the book
     * @see https://dev.predict.fun/get-order-match-events-25663812e0
     * @param {string} [outcome] unified outcome handle, restricts the call to that outcome's market
     * @param {int} [since] timestamp in ms of the earliest trade to return, applied client side
     * @param {int} [limit] the maximum number of trades to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.after] cursor from a previous response, the venue pages back from the most recent match
     * @param {bool} [params.isSignerMaker] true keeps only the matches the wallet rested, false only the ones it took
     * @param {string} [params.signerAddress] read another wallet's matches instead of the configured one
     * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public async override Task<List<ccxt.PredictionTrade>> FetchMyTrades(string outcome = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string? signerAddress = this.safeString(parameters, "signerAddress", this.walletAddress);
        if ((signerAddress == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchMyTrades() requires a walletAddress, or a \"signerAddress\" parameter for any other address")) ;
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "signerAddress", signerAddress },
        };
        IDictionary<string, object> outcomeObj = null;
        if ((outcome != null))
        {
            await this.loadOutcome(outcome);
            outcomeObj = this.outcome(outcome);
            IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            request["marketId"] = this.safeString(info, "marketId");
        }
        object query = this.omit(parameters, "signerAddress");
        // the endpoint carries no time filter, it pages back from the most recent match, so
        // since is applied client side by parsePredictionTrades
        Dictionary<string, object> response = await this.predictfunGetV1OrdersMatches(this.extend(request, query));
        // the venue answers with the shape documented in fetchTrades below
        List<object> data = this.safeList(response, "data", new List<object>() {});
        string wallet = signerAddress.ToLower();
        // a settlement names one taker and several makers, and the wallet may sit on either side,
        // so the legs it signed are the ones to report - a self trade legitimately yields two rows
        List<object> flattenTrades = new List<object>() {};
        int dataLength = data.Count;
        for (int i = 0; i < dataLength; i++)
        {
            object entry = getValue(data, i);
            IDictionary<string, object> taker = this.safeDict(entry, "taker", new Dictionary<string, object>() {});
            string? takerSigner = this.safeStringLower(taker, "signer");
            if ((takerSigner == wallet))
            {
                Dictionary<string, object> takerParty = this.extend(taker, new Dictionary<string, object>() {
                    { "role", "taker" },
                    { "takerOrMaker", "taker" },
                    { "type", "market" },
                });
                flattenTrades.Add(this.extend(entry, new Dictionary<string, object>() {
                    { "partyToParse", takerParty },
                }));
            }
            List<object> makers = this.safeList(entry, "makers", new List<object>() {});
            int makersLength = makers.Count;
            for (int j = 0; j < makersLength; j++)
            {
                object maker = getValue(makers, j);
                string? makerSigner = this.safeStringLower(maker, "signer");
                if ((makerSigner == wallet))
                {
                    Dictionary<string, object> makerParty = this.extend(maker, new Dictionary<string, object>() {
                        { "role", "maker" },
                        { "takerOrMaker", "maker" },
                        { "type", "limit" },
                    });
                    flattenTrades.Add(this.extend(entry, new Dictionary<string, object>() {
                        { "partyToParse", makerParty },
                    }));
                }
            }
        }
        return ccxt.BaseExchange.ToPredictionTradeList(this.parsePredictionTrades(flattenTrades, outcomeObj, since, limit));
    }

    /**
     * @method
     * @name predictfun#fetchTrades
     * @description fetches the most recent settled matches for a single prediction outcome token
     * @see https://dev.predict.fun/get-order-match-events-25663812e0
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {int} [since] timestamp in ms of the earliest trade to return, applied client side
     * @param {int} [limit] the maximum number of trades to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.after] cursor from a previous response, the venue pages back from the most recent match
     * @param {string} [params.minValueUsdtWei] only return matches worth at least this many wei
     * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public async override Task<List<ccxt.PredictionTrade>> FetchTrades(string outcome, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "marketId", this.safeString(info, "marketId") },
        };
        // the endpoint carries no time filter, it pages back from the most recent match, so
        // since is applied client side by parsePredictionTrades
        Dictionary<string, object> response = await this.predictfunGetV1OrdersMatches(this.extend(request, parameters));
        //
        //     {
        //         "cursor": "eyJjcmVhdGVkQXQiOiIyMDI2LTA5LTA1VDIzOjU1OjU2WiJ9",
        //         "data": [
        //             {
        //                 "amountFilled": "8409090909090909720",
        //                 "executedAt": "2026-09-06T11:45:23.000Z",
        //                 "priceExecuted": "111200000000000000",
        //                 "settlementId": "01a07689-955a-7070-86af-a100b7b7350c",
        //                 "transactionHash": "0x435863c29443ff45b2f8966c52428d3bb3a29a38de24dc6c17ca0817951fda79",
        //                 "taker": {
        //                     "amount": "8409090909090909720",
        //                     "fee": { "amount": "151363636363636374", "type": "SHARES" },
        //                     "hash": "0x0a0eab35c68fda64ced0989aec9313f5884e5ecba51d780f9b7da634cc979027",
        //                     "outcome": { "indexSet": 1, "name": "Up", "onChainId": "44616422429987613582483910707767544579739686077414897363305263997555112684875" },
        //                     "price": "112000000000000000",
        //                     "quoteType": "Bid",
        //                     "signer": "0x6Da6Cb464F92AE7aD4Ec3d239c81719Cb1D0Ae03"
        //                 },
        //                 "makers": [
        //                     {
        //                         "amount": "1009090909090909720",
        //                         "fee": { "amount": "0", "type": "SHARES" },
        //                         "hash": "0x0950ef588b53e2489f95cb1d830a6e0cb0bffc0f4baf4286e3b2e03bad2eba47",
        //                         "outcome": { "indexSet": 2, "name": "Down", "onChainId": "39857821499700810175970492505692306870421072168717601114846981613437602260320" },
        //                         "price": "880000000000000000",
        //                         "quoteType": "Bid",
        //                         "signer": "0x6Da6Cb464F92AE7aD4Ec3d239c81719Cb1D0Ae03"
        //                     }
        //                 ],
        //                 "market": { "id": 1965449 }
        //             }
        //         ],
        //         "success": true
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        List<object> flattenTrades = new List<object>() {};
        int dataLength = data.Count;
        for (int i = 0; i < dataLength; i++)
        {
            IDictionary<string, object> entry = this.safeDict(data, i);
            IDictionary<string, object> taker = this.safeDict(entry, "taker", new Dictionary<string, object>() {});
            IDictionary<string, object> takerOutcome = this.safeDict(taker, "outcome", new Dictionary<string, object>() {});
            Int64? takerIndexSet = this.safeInteger(takerOutcome, "indexSet");
            Int64? outcomeIndexSet = this.safeInteger(info, "indexSet");
            object partyToParse = this.safeDict(entry, "taker", new Dictionary<string, object>() {});
            if ((takerIndexSet == outcomeIndexSet))
            {
                // a public print carries no takerOrMaker: the unified fetchTrades contract allows
                // only 'taker' or nothing there, and the leg that matches the requested outcome is
                // genuinely the maker one whenever the taker crossed into the opposite outcome.
                // the role is kept for pricing and surfaces as the type of the order behind the leg
                Dictionary<string, object> takerParty = new Dictionary<string, object>() {
                    { "role", "taker" },
                    { "type", "market" },
                };
                partyToParse = this.extend(partyToParse, takerParty);
                flattenTrades.Add(this.extend(entry, new Dictionary<string, object>() {
                    { "partyToParse", partyToParse },
                }));
            } else
            {
                List<object> makers = this.safeList(entry, "makers", new List<object>() {});
                int makersLength = makers.Count;
                Dictionary<string, object> makerParty = new Dictionary<string, object>() {
                    { "role", "maker" },
                    { "type", "limit" },
                };
                for (int j = 0; j < makersLength; j++)
                {
                    object maker = getValue(makers, j);
                    IDictionary<string, object> makerOutcome = this.safeDict(maker, "outcome", new Dictionary<string, object>() {});
                    Int64? makerIndexSet = this.safeInteger(makerOutcome, "indexSet");
                    if ((makerIndexSet == outcomeIndexSet))
                    {
                        partyToParse = maker;
                        partyToParse = this.extend(partyToParse, makerParty);
                        flattenTrades.Add(this.extend(entry, new Dictionary<string, object>() {
                            { "partyToParse", partyToParse },
                        }));
                    }
                }
            }
        }
        return ccxt.BaseExchange.ToPredictionTradeList(this.parsePredictionTrades(flattenTrades, outcomeObj, since, limit));
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parsePredictionTrade
     * @description parses a raw order match event into a unified prediction trade for one of the two outcomes
     * @param {object} trade the raw match event
     * @param {object} [market] the outcome the trade belongs to
     * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public override Dictionary<string, object> parsePredictionTrade(object trade, object market = null)
    {
        IDictionary<string, object> party = this.safeDict(trade, "partyToParse", new Dictionary<string, object>() {});
        // fetchMyTrades spans several markets at once, so the row's identity comes from the party
        // it carries rather than from the outcome the caller asked for
        IDictionary<string, object> partyOutcome = this.safeDict(party, "outcome", new Dictionary<string, object>() {});
        string? tokenId = this.safeString(partyOutcome, "onChainId");
        object outcomeObj = this.outcomeForToken(tokenId, market);
        string? role = this.safeString(party, "role");
        // a resting maker fills at its own price, so the party price is the execution price for
        // that leg. the taker's party price is only its limit: the settlement records what it
        // actually paid, and the difference is the price improvement the book gave it
        string? priceStr = this.safeString(party, "price");
        if (role == "taker")
        {
            priceStr = this.safeString(trade, "priceExecuted", priceStr);
        }
        priceStr = Precise.stringDiv(priceStr, "1000000000000000000");
        string? amountStr = this.safeString(party, "amount");
        amountStr = Precise.stringDiv(amountStr, "1000000000000000000");
        string? side = null;
        string? order = null;
        Dictionary<string, object> fee = null;
        string? quoteType = this.safeStringLower(party, "quoteType");
        if (quoteType == "bid")
        {
            side = "buy";
        } else if (quoteType == "ask")
        {
            side = "sell";
        }
        order = this.safeString(party, "hash");
        IDictionary<string, object> rawFee = this.safeDict(party, "fee");
        if ((rawFee != null))
        {
            string? feeType = this.safeString(rawFee, "type");
            string? feeCost = this.safeString(rawFee, "amount");
            fee = new Dictionary<string, object>() {
                { "currency", (feeType == "COLLATERAL") ? "USDT" : null },
                { "cost", this.parseNumber(Precise.stringDiv(feeCost, "1000000000000000000")) },
            };
        }
        Int64? timestamp = this.parse8601(this.safeString(trade, "executedAt"));
        return this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", this.safeString(trade, "settlementId") },
            { "order", order },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "outcome", this.safeOutcomeSymbol(null, outcomeObj) },
            { "outcomeId", this.safeString(outcomeObj, "outcomeId") },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "type", this.safeString(party, "type") },
            { "side", side },
            { "takerOrMaker", this.safeString(party, "takerOrMaker") },
            { "price", this.parseNumber(priceStr) },
            { "amount", this.parseNumber(amountStr) },
            { "cost", null },
            { "fee", fee },
            { "info", this.omit(trade, "partyToParse") },
        });
    }

    /**
     * @method
     * @name predictfun#setSandboxMode
     * @description switches between BNB mainnet and the BNB testnet
     * @param {bool} enable whether to use the testnet
     * @returns {undefined}
     */
    public override void setSandboxMode(object enable)
    {
        // read before the flag is overwritten: only an actual switch touches the token, so calling
        // this twice with the same value is a no-op rather than a forced re-authentication
        bool? wasSandbox = this.safeBool(this.options, "sandboxMode", false);
        base.setSandboxMode(enable);
        // the testnet is a different chain, so the EIP-712 chainId and every verifying contract
        // change with it - and the venue serves the testnet without an api key
        this.options["sandboxMode"] = enable;
        this.options["chainId"] = isTrue((enable)) ? 97 : 56;
        ((IDictionary<string,object>)this.requiredCredentials)["apiKey"] = !isTrue(enable);
        if (!isEqual(wasSandbox, enable))
        {
            // a token minted for one host is not valid on the other, so the live one is set aside
            // on the way in and taken back on the way out - a round trip through the sandbox then
            // costs no re-authentication. the sandbox token is not kept: it dies with the switch
            if (isTrue(enable))
            {
                this.options["backupJwtToken"] = this.safeString(this.options, "jwtToken");
                this.options["backupJwtTokenExpiresAt"] = this.safeInteger(this.options, "jwtTokenExpiresAt", 0);
                this.options["jwtToken"] = null;
                this.options["jwtTokenExpiresAt"] = 0;
            } else
            {
                this.options["jwtToken"] = this.safeString(this.options, "backupJwtToken");
                this.options["jwtTokenExpiresAt"] = this.safeInteger(this.options, "backupJwtTokenExpiresAt", 0);
                this.options["backupJwtToken"] = null;
                this.options["backupJwtTokenExpiresAt"] = 0;
            }
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#hashMessage
     * @description hashes a message the way eth_personal_sign does, prefixing it before the keccak
     * @param {string} message the message to hash
     * @returns {string} the 0x prefixed hash
     */
    public virtual object hashMessage(object message)
    {
        string? binaryMessage = this.encode(message);
        object binaryMessageLength = this.binaryLength(binaryMessage);
        byte[] x19 = this.base16ToBinary("19");
        byte[] newline = this.base16ToBinary("0a");
        byte[] prefix = this.binaryConcat(x19, this.encode("Ethereum Signed Message:"), newline, this.encode(this.numberToString(binaryMessageLength)));
        return ("0x" + (this.hash(this.binaryConcat(prefix, binaryMessage), keccak, "hex")));
    }

    /**
     * @ignore
     * @method
     * @name predictfun#signHash
     * @description signs a 32 byte hash with the wallet's private key
     * @param {string} hash the hash to sign
     * @param {string} privateKey the wallet private key
     * @returns {string} the 65 byte signature, 0x prefixed
     */
    public virtual string signHash(object hash, object privateKey)
    {
        Dictionary<string, object> signature = ecdsa(((hash == null) ? null : ((string)hash).Substring(Math.Max(((string)hash).Length - 64, 0))), ((privateKey == null) ? null : ((string)privateKey).Substring(Math.Max(((string)privateKey).Length - 64, 0))), secp256k1, null);
        // assign before padStart so the php str_pad regex matches, it only handles a bare identifier
        string? rRaw = ((string)(signature != null && ((IDictionary<string, object>)signature).ContainsKey("r") ? ((IDictionary<string, object>)signature)["r"] : null));
        string? sRaw = ((string)(signature != null && ((IDictionary<string, object>)signature).ContainsKey("s") ? ((IDictionary<string, object>)signature)["s"] : null));
        string r = (rRaw as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"));
        string s = (sRaw as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"));
        // ecrecover wants v in {27,28} while the raw recovery id is {0,1}
        string v = this.intToBase16(this.sum(27, (signature != null && ((IDictionary<string, object>)signature).ContainsKey("v") ? ((IDictionary<string, object>)signature)["v"] : null)));
        // assign before toLowerCase so the php regex matches, it only handles a bare identifier
        string signatureHex = ((("0x" + r) + s) + v);
        return signatureHex.ToLower();
    }

    /**
     * @ignore
     * @method
     * @name predictfun#authenticate
     * @description exchanges a wallet signature for the JWT that authorises order actions, and caches it
     * @see https://dev.predict.fun/get-auth-message-25326899e0
     * @see https://dev.predict.fun/get-jwt-with-valid-signature-25326900e0
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {string} the JWT
     */
    public async virtual Task<string?> authenticate(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (((this.walletAddress == null)) || ((this.privateKey == null)))
        {
            throw new ArgumentsRequired ((this.id + " authenticate() requires a walletAddress and a privateKey")) ;
        }
        Int64 now = this.milliseconds();
        string? cached = this.safeString(this.options, "jwtToken");
        Int64? expiresAt = this.safeInteger(this.options, "jwtTokenExpiresAt", 0);
        // a token outlives its window silently: the venue answers 401 on every order action once
        // it lapses, so re-issue before that rather than after the first failure
        if (((cached != null)) && (isLessThan(now, expiresAt)))
        {
            return cached;
        }
        Dictionary<string, object> messageResponse = await this.predictfunGetV1AuthMessage(parameters);
        //
        //     { "data": { "message": "Sign this message to authenticate ..." }, "success": true }
        //
        IDictionary<string, object> messageData = this.safeDict(messageResponse, "data", new Dictionary<string, object>() {});
        string? message = this.safeString(messageData, "message");
        if ((message == null))
        {
            throw new AuthenticationError ((this.id + " authenticate() got an auth reply without the \"message\" field to sign")) ;
        }
        string signature = this.signHash(this.hashMessage(message), this.privateKey);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "signer", this.walletAddress },
            { "message", message },
            { "signature", signature },
        };
        Dictionary<string, object> response = await this.predictfunPostV1Auth(request);
        //
        //     { "data": { "token": "eyJhbGciOi..." }, "success": true }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        string? token = this.safeString(data, "token");
        if ((token == null))
        {
            throw new AuthenticationError ((this.id + " authenticate() did not return a token")) ;
        }
        this.options["jwtToken"] = token;
        // measured from before the round trip, so the cached window closes a little early rather
        // than a little late
        Int64? tokenExpiresIn = this.safeInteger(this.options, "tokenExpiresIn", 86400000);
        this.options["jwtTokenExpiresAt"] = this.sum(now, tokenExpiresIn);
        return token;
    }

    /**
     * @ignore
     * @method
     * @name predictfun#signPredictfunOrder
     * @description signs a contract order with the EIP-712 scheme of the exchange that settles it
     * @param {object} order the contract order, as sent to the venue
     * @param {bool} isNegRisk whether the market settles through the negative risk exchange
     * @param {bool} isYieldBearing whether the market settles through the yield bearing exchange
     * @returns {object} a dictionary with the order hash and the signature
     */
    public virtual object signPredictfunOrder(object order, object isNegRisk, object isYieldBearing)
    {
        // chainIdValue, not chainId - the php regex transpiler rewrites the substring "chainId"
        // inside the domain literal to a local var, which would corrupt the domain type hash
        Int64? chainIdValue = this.safeInteger(this.options, "chainId", 56);
        string? verifyingContract = ((string)this.exchangeAddress(isNegRisk, isYieldBearing));
        Dictionary<string, object> domain = new Dictionary<string, object>() {
            { "name", "predict.fun CTF Exchange" },
            { "version", "1" },
            { "chainId", chainIdValue },
            { "verifyingContract", verifyingContract },
        };
        List<object> orderStruct = new List<object>() {new Dictionary<string, object>() {
    { "name", "salt" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "maker" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "signer" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "taker" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "tokenId" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "makerAmount" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "takerAmount" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "expiration" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "nonce" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "feeRateBps" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "side" },
    { "type", "uint8" },
}, new Dictionary<string, object>() {
    { "name", "signatureType" },
    { "type", "uint8" },
}};
        // ethEncodeStructuredData returns the EIP-712 digest, which is both what gets signed and
        // the order hash the venue indexes the order by
        byte[] encoded = this.ethEncodeStructuredData(domain, new Dictionary<string, object>() {
            { "Order", orderStruct },
        }, order);
        // ethEncodeStructuredData returns the 0x1901 || domainSeparator || structHash preimage,
        // the digest that gets signed - and that the venue indexes the order by - is its keccak
        string hash = ("0x" + (this.hash(encoded, keccak, "hex")));
        return new Dictionary<string, object>() {
            { "hash", hash },
            { "signature", this.signHash(hash, this.privateKey) },
        };
    }

    /**
     * @method
     * @name predictfun#createOrder
     * @description creates a LIMIT or MARKET order on a single prediction outcome token
     * @see https://dev.predict.fun/create-an-order-32534694e0
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {string} type 'limit' or 'market'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount the number of outcome shares
     * @param {float} [price] the price per share between 0 and 1, required for a limit order, and for a market order too unless warnOnMarketOrderWithoutPrice is turned off
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.expiration] unix timestamp in seconds the limit order expires at
     * @param {bool} [params.postOnly] reject the order if it would take liquidity
     * @param {bool} [params.isFillOrKill] fill the order completely or cancel it
     * @param {string} [params.slippageBps] slippage tolerance for a market order, in basis points
     * @param {bool} [params.warnOnMarketOrderWithoutPrice] set to false to sign a priceless market order at 0.99 to buy or 0.01 to sell, the worst price it accepts
     * @param {string} [params.selfTradePrevention] 'CANCEL_MAKER' | 'CANCEL_TAKER' | 'CANCEL_BOTH'
     * @param {string} [params.salt] order salt, pin it to retry an order idempotently
     * @param {string} [params.nonce] the maker's on chain nonce, defaults to 0
     * @param {string} [params.feeRateBps] fee in basis points, read from the market when omitted
     * @param {bool} [params.isNegRisk] override the market's negative risk flag
     * @param {bool} [params.isYieldBearing] override the market's yield bearing flag
     * @returns {object} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CreateOrder(string outcome, string type, string side, double amount, double? price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        string? tokenId = this.safeString(outcomeObj, "outcomeId");
        if ((tokenId == null))
        {
            throw new ArgumentsRequired (((this.id + " createOrder() could not resolve the on chain token id of ") + outcome)) ;
        }
        string strategy = "LIMIT";
        if ((type == "market"))
        {
            strategy = "MARKET";
        }
        bool isMarket = (strategy == "MARKET");
        if ((!isMarket) && ((price == null)))
        {
            throw new ArgumentsRequired ((this.id + " createOrder() requires a \"price\" argument for a limit order")) ;
        }
        bool isBuy = ((side == "buy"));
        // amounts cross the wire as collateral wei, the venue truncates the price to three
        // significant digits and the quantity to five, so send what it will actually use
        // the venue sizes an order from both legs and refuses anything else: a limitless style
        // takerAmount sentinel of 1 is rejected as create_order_min_order_value_not_met (the order
        // value is read off the taker leg) and signing at the maximum price of 1 is rejected as
        // create_order_price_out_of_range (it wants 0 < price < 1)
        string? amountString = this.numberToString(amount);
        string? priceString = this.numberToString(price);
        string? priceToProvide = priceString;
        // read through the extractor rather than off the instance, so one call can opt in without
        // reconfiguring the exchange - and so the key is taken out of params instead of riding
        // along into the request body
        bool? warnOnMarketOrderWithoutPrice = true;
        IList<object> warnOnMarketOrderWithoutPriceparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "createOrder", "warnOnMarketOrderWithoutPrice", true);
        warnOnMarketOrderWithoutPrice = (bool?)warnOnMarketOrderWithoutPriceparametersVariable[0];
        parameters = warnOnMarketOrderWithoutPriceparametersVariable[1];
        if ((price == null))
        {
            // a priceless limit order already threw above, so this is a market order
            if ((warnOnMarketOrderWithoutPrice == true))
            {
                throw new ArgumentsRequired ((this.id + " createOrder() market orders require a \"price\" argument. To use default values turn \"warnOnMarketOrderWithoutPrice\" off in options")) ;
            }
            // it still has to name a price, so it takes the aggressive end of the range the venue
            // allows: 0.99 crosses any ask, 0.01 is crossed by any bid. the fill happens at the
            // book's own prices, this is only the worst price the order accepts - which is also
            // the collateral the maker leg has to cover
            priceToProvide = isBuy ? this.numberToString(this.safeNumber(this.options, "marketBuyPrice", 0.99)) : this.numberToString(this.safeNumber(this.options, "marketSellPrice", 0.01));
        }
        string? quantityWei = Precise.stringMul(amountString, "1000000000000000000");
        string? priceWei = Precise.stringMul(priceToProvide, "1000000000000000000");
        // the collateral leg follows from the price and the size, exactly as for a limit order -
        // both legs have to agree or the venue rejects the order
        string? costWei = Precise.stringMul(priceToProvide, quantityWei);
        string? makerAmount = quantityWei;
        string? takerAmount = costWei;
        if (isBuy)
        {
            // a buy pays collateral for shares, a sell hands over shares for collateral
            makerAmount = costWei;
            takerAmount = quantityWei;
        }
        string? slippageBps = this.safeString(parameters, "slippageBps", "0");
        if (Precise.stringGt(slippageBps, "0"))
        {
            if (isBuy)
            {
                // widen what the taker is willing to pay, capped at one unit of collateral a share
                makerAmount = Precise.stringMin(Precise.stringDiv(Precise.stringMul(makerAmount, Precise.stringAdd("10000", slippageBps)), "10000"), quantityWei);
            } else
            {
                takerAmount = Precise.stringMax(Precise.stringDiv(Precise.stringMul(takerAmount, Precise.stringSub("10000", slippageBps)), "10000"), "0");
            }
        }
        // feeRateBps and the two exchange selectors live on the market row, not on the outcome
        // row - signing with the wrong pair places the order under a different verifying contract
        // and the venue answers create_order_hash_mismatch
        string? marketSymbol = this.safeString(outcomeObj, "market");
        IDictionary<string, object> marketObj = this.safeDict(this.markets, marketSymbol, new Dictionary<string, object>() {});
        IDictionary<string, object> marketRow = this.safeDict(marketObj, "info", new Dictionary<string, object>() {});
        string? marketFeeRateBps = this.safeString(marketRow, "feeRateBps", "200"); // should be at least 200
        string? feeRateBps = this.safeString(parameters, "feeRateBps", marketFeeRateBps);
        bool? marketIsNegRisk = this.safeBool(marketRow, "isNegRisk", false);
        bool? isNegRisk = this.safeBool(parameters, "isNegRisk", marketIsNegRisk);
        bool? marketIsYieldBearing = this.safeBool(marketRow, "isYieldBearing", false);
        bool? isYieldBearing = this.safeBool(parameters, "isYieldBearing", marketIsYieldBearing);
        Int64? defaultExpiration = this.safeInteger(this.options, "defaultExpiration", 3600); // 1 hour
        Int64? expirationDelta = defaultExpiration;
        object expiration = this.safeInteger(parameters, "expiration");
        if (isEqual(expiration, null))
        {
            if (isMarket)
            {
                expirationDelta = this.safeInteger(this.options, "marketOrderExpiration", defaultExpiration);
            }
            Int64 now = this.seconds();
            expiration = this.sum(now, expirationDelta);
        }
        Int64? nonce = this.incrementingNonce();
        string? salt = this.safeString(parameters, "salt", this.numberToString(nonce));
        object taker = "0x0000000000000000000000000000000000000000";
        IList<object> takerparametersVariable = (IList<object>)this.handleOptionAndParams(parameters, "createOrder", "taker", taker);
        taker = takerparametersVariable[0];
        parameters = takerparametersVariable[1];
        Dictionary<string, object> contractOrder = new Dictionary<string, object>() {
            { "salt", salt },
            { "maker", this.walletAddress },
            { "signer", this.walletAddress },
            { "taker", taker },
            { "tokenId", tokenId },
            { "makerAmount", this.decimalToPrecision(makerAmount, TRUNCATE, 0, DECIMAL_PLACES) },
            { "takerAmount", this.decimalToPrecision(takerAmount, TRUNCATE, 0, DECIMAL_PLACES) },
            { "expiration", expiration },
            { "nonce", this.safeString(parameters, "nonce", "0") },
            { "feeRateBps", feeRateBps },
            { "side", isBuy ? 0 : 1 },
            { "signatureType", 0 },
        };
        object signed = this.signPredictfunOrder(contractOrder, isNegRisk, isYieldBearing);
        Dictionary<string, object> orderPayload = this.extend(contractOrder, new Dictionary<string, object>() {
            { "hash", this.safeString(signed, "hash") },
            { "signature", this.safeString(signed, "signature") },
        });
        Dictionary<string, object> data = new Dictionary<string, object>() {
            { "order", orderPayload },
            { "pricePerShare", this.decimalToPrecision(priceWei, TRUNCATE, 0, DECIMAL_PLACES) },
            { "strategy", strategy },
        };
        bool? postOnly = this.safeBool(parameters, "isPostOnly", false);
        IList<object> postOnlyparametersVariable = (IList<object>)this.handlePostOnly(isMarket, postOnly, parameters);
        postOnly = (bool?)postOnlyparametersVariable[0];
        parameters = postOnlyparametersVariable[1];
        if ((postOnly == true))
        {
            data["isPostOnly"] = postOnly;
        }
        string? timeInForce = this.safeStringUpper(parameters, "timeInForce");
        if (timeInForce == "FOK")
        {
            data["isFillOrKill"] = true;
        }
        // documented, and the venue takes it inside data rather than as a top level key
        string? selfTradePrevention = this.safeStringUpper(parameters, "selfTradePrevention");
        if ((selfTradePrevention != null))
        {
            data["selfTradePrevention"] = selfTradePrevention;
        }
        // every param the method consumes itself has to come out, otherwise it survives into the
        // extend below and is posted as a top level key next to 'data'
        parameters = this.omit(parameters, new List<object>() {"isPostOnly", "timeInForce", "isFillOrKill", "feeRateBps", "isNegRisk", "isYieldBearing", "slippageBps", "salt", "nonce", "expiration", "selfTradePrevention", "taker"});
        // the JWT authorises the order, the api key only authorises the request
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "data", data },
        };
        Dictionary<string, object> response = await this.predictfunPostV1Orders(this.extend(request, parameters));
        //
        //     {
        //         "data": {
        //             "code": "OK",
        //             "orderHash": "0x5ae1a7893b1a804530151dec3866cd0bb8ffe4e4c3640aca1b3ab5ef26c57747",
        //             "orderId": "415535",
        //             "removalLockedUntil": null
        //         },
        //         "success ": true
        //     }
        //
        IDictionary<string, object> result = this.safeDict(response, "data", new Dictionary<string, object>() {});
        // the venue answers with an id and a hash and nothing else - no price, size, side or
        // status - so the returned order is built from what was requested and signed, with only
        // the identifiers taken from the response
        return ccxt.BaseExchange.ToPredictionOrder(this.safePredictionOrder(new Dictionary<string, object>() {             { "id", this.safeString2(result, "orderHash", "hash") },             { "clientOrderId", null },             { "info", response },             { "timestamp", null },             { "datetime", null },             { "status", null },             { "outcome", this.safeString(outcomeObj, "outcome", outcome) },             { "outcomeId", this.safeString(outcomeObj, "outcomeId") },             { "label", this.safeString(outcomeObj, "label") },             { "market", this.safeString(outcomeObj, "market") },             { "event", this.safeString(outcomeObj, "event") },             { "type", type },             { "side", side },             { "price", this.parseNumber(priceString) },             { "amount", this.parseNumber(amountString) },             { "filled", null },             { "remaining", null },             { "cost", null },             { "fee", null },             { "trades", new List<object>() {} },         }));
    }

    /**
     * @method
     * @name predictfun#fetchPositions
     * @description fetches the outcome shares the wallet holds
     * @see https://dev.predict.fun/get-positions-32675933e0
     * @see https://dev.predict.fun/get-positions-by-address-32675934e0
     * @param {string[]} [outcomes] unified outcome handles to keep, all of them when omitted
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.address] read another wallet's positions, which needs no JWT
     * @param {string} [params.marketId] only positions on this market
     * @param {bool} [params.isResolved] only resolved, or only unresolved, positions
     * @param {string} [params.sort] 'AMOUNT_DESC' | 'EVENT_BLOCK_ASC' | 'EVENT_BLOCK_DESC' | 'SHARES_VALUE_DESC' | 'RETURN_DESC'
     * @param {int} [params.first] the maximum number of positions to return
     * @param {string} [params.after] cursor from a previous response
     * @returns {object[]} a list of [position structures](https://docs.ccxt.com/#/?id=position-structure)
     */
    public async override Task<List<ccxt.PredictionPosition>> FetchPositions(object outcomes = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        int outcomesLength = 0;
        if ((outcomes != null))
        {
            outcomesLength = getArrayLength(outcomes);
            await this.loadOutcomes(outcomes);
        }
        string? address = this.safeString(parameters, "address");
        Dictionary<string, object> response = null;
        if ((address != null))
        {
            // the by-address endpoint reads any wallet and is happy with just the api key
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "address", address },
            };
            object rest = this.omit(parameters, "address");
            response = await this.predictfunGetV1PositionsAddress(this.extend(request, rest));
        } else
        {
            // the JWT is what names the wallet whose positions come back
            await this.authenticate();
            response = await this.predictfunGetV1Positions(parameters);
        }
        //
        //     {
        //         "cursor": "eyJtYXJrZXRJZCI6MjAzMjU3OCwib3V0Y29tZUlkIjo0MDAyOTQ3fQ==",
        //         "data": [
        //             {
        //                 "id": "eyJtYXJrZXRJZCI6MjAzMjU4MSwib3V0Y29tZUlkIjo0MDAyOTUyfQ==",
        //                 "amount": "11819508771929824562",
        //                 "averageBuyPriceUsd": "0.57",
        //                 "pnlUsd": 0,
        //                 "valueUsd": 6.74,
        //                 "market": { "id": 2032581, "categorySlug": "btc-updown-5m-1788776400", "status": "REGISTERED", "tradingStatus": "OPEN" },
        //                 "outcome": {
        //                     "indexSet": 1,
        //                     "name": "Up",
        //                     "onChainId": "104613341090911893615899927839535241203421132680281479852748534361460565051967",
        //                     "status": null,
        //                     "bestBid": { "price": 0.57, "size": 192.88842738205366 },
        //                     "bestAsk": { "price": 0.58, "size": 58 }
        //                 }
        //             }
        //         ],
        //         "success": true
        //     }
        //
        List<object> rows = this.safeList(response, "data", new List<object>() {});
        List<object> parsed = this.parsePredictionPositions(rows);
        if ((outcomesLength == 0))
        {
            return ccxt.BaseExchange.ToPredictionPositionList(parsed);
        }
        // the venue filters by marketId only, so a set of outcome handles is applied here
        Dictionary<string, object> wanted = new Dictionary<string, object>() {};
        IList<object> wantedOutcomes = this.toArray(outcomes);
        for (int i = 0; i < outcomesLength; i++)
        {
            IDictionary<string, object> outcomeObj = this.outcome(getValue(wantedOutcomes, i));
            string? wantedId = this.safeString(outcomeObj, "outcomeId", "");
            wanted[(string)wantedId] = true;
        }
        List<object> result = new List<object>() {};
        int parsedLength = (parsed?.Count ?? 0);
        for (int i = 0; i < parsedLength; i++)
        {
            IDictionary<string, object> position = ((IDictionary<string, object>)getValue(parsed, i));
            string? outcomeId = this.safeString(position, "outcomeId");
            if (((outcomeId != null)) && (((outcomeId != null) && wanted.ContainsKey(outcomeId))))
            {
                result.Add(position);
            }
        }
        return ccxt.BaseExchange.ToPredictionPositionList(result);
    }

    /**
     * @method
     * @name predictfun#fetchPosition
     * @description fetches the shares the wallet holds of a single outcome
     * @see https://dev.predict.fun/get-positions-32675933e0
     * @param {string} outcome unified outcome handle, or an outcome token id
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.address] read another wallet's position, which needs no JWT
     * @returns {object} a [position structure](https://docs.ccxt.com/#/?id=position-structure)
     */
    public async override Task<ccxt.PredictionPosition> FetchPosition(string outcome, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
        // scope the call to the outcome's market so the wallet's other positions are not paged through
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "marketId", this.safeString(info, "marketId") },
        };
        List<object> positions = ccxt.BaseExchange.FromPredictionPositionList(await this.FetchPositions(new List<object>() {outcome}, this.extend(request, parameters)));
        // holding none of an outcome is an ordinary read, so the empty slot is returned rather
        // than raised - the same shape polymarket and binance answer with
        return ccxt.BaseExchange.ToPredictionPosition(this.safeDict(positions, 0));
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parsePredictionPosition
     * @description parses a raw position row into the unified position structure
     * @param {object} position the raw position row
     * @param {object} [market] not used by predictfun parsePredictionPosition
     * @returns {object} a [position structure](https://docs.ccxt.com/#/?id=position-structure)
     */
    public override Dictionary<string, object> parsePredictionPosition(object position, object market = null)
    {
        IDictionary<string, object> rawOutcome = this.safeDict(position, "outcome", new Dictionary<string, object>() {});
        IDictionary<string, object> rawMarket = this.safeDict(position, "market", new Dictionary<string, object>() {});
        string? tokenId = this.safeString(rawOutcome, "onChainId");
        object outcomeObj = this.outcomeForToken(tokenId, market);
        // shares are collateral wei, the usd figures come back already scaled
        string? contracts = Precise.stringDiv(this.safeString(position, "amount"), "1000000000000000000");
        string? entryPrice = this.safeString(position, "averageBuyPriceUsd");
        string? notional = this.safeString(position, "valueUsd");
        string? pnl = this.safeString(position, "pnlUsd");
        // what the shares cost, which is also the collateral committed to the position
        string? collateral = Precise.stringMul(entryPrice, contracts);
        string? markPrice = null;
        if (((notional != null)) && ((contracts != null)) && Precise.stringGt(contracts, "0"))
        {
            markPrice = Precise.stringDiv(notional, contracts);
        }
        string? percentage = null;
        if (((pnl != null)) && ((collateral != null)) && Precise.stringGt(collateral, "0"))
        {
            percentage = Precise.stringMul(Precise.stringDiv(pnl, collateral), "100");
        }
        // a settled outcome reports WON or LOST, an open one leaves the field null - and the
        // market can read RESOLVED while the outcome has not been marked yet, so the two are
        // tracked apart: the position is resolved, but which side won is not yet known
        string? outcomeStatus = this.safeString(rawOutcome, "status");
        string? marketStatus = this.safeString(rawMarket, "status");
        bool settled = (outcomeStatus == "WON") || (outcomeStatus == "LOST");
        bool resolved = settled || (marketStatus == "RESOLVED") || (marketStatus == "SETTLED");
        bool? won = null;
        string? settleFraction = null;
        string? payout = null;
        if (settled)
        {
            won = (outcomeStatus == "WON");
            settleFraction = won == true ? "1" : "0";
            // a winning share redeems for one unit of collateral, a losing one for nothing
            payout = won == true ? contracts : "0";
        }
        // pnl is realized once the market has resolved, unrealized while it is still trading
        string? realizedPnl = null;
        string? unrealizedPnl = pnl;
        if (resolved)
        {
            realizedPnl = pnl;
            unrealizedPnl = null;
        }
        return this.safePredictionPosition(new Dictionary<string, object>() {
            { "id", this.safeString(position, "id") },
            { "timestamp", null },
            { "datetime", null },
            { "contracts", this.parseNumber(contracts) },
            { "contractSize", 1 },
            { "side", "long" },
            { "notional", this.parseNumber(notional) },
            { "unrealizedPnl", this.parseNumber(unrealizedPnl) },
            { "realizedPnl", this.parseNumber(realizedPnl) },
            { "collateral", this.parseNumber(collateral) },
            { "entryPrice", this.parseNumber(entryPrice) },
            { "markPrice", this.parseNumber(markPrice) },
            { "lastPrice", null },
            { "percentage", this.parseNumber(percentage) },
            { "resolved", resolved },
            { "won", won },
            { "settleFraction", this.parseNumber(settleFraction) },
            { "payout", this.parseNumber(payout) },
            { "outcome", this.safeOutcomeSymbol(null, outcomeObj) },
            { "outcomeId", this.safeString(outcomeObj, "outcomeId", tokenId) },
            { "label", this.safeString(outcomeObj, "label", this.safeStringUpper(rawOutcome, "name")) },
            { "market", this.safeString(outcomeObj, "market") },
            { "event", this.safeString(outcomeObj, "event") },
            { "info", position },
        });
    }

    /**
     * @method
     * @name predictfun#cancelOrder
     * @description removes one of your own orders from the order book
     * @see https://dev.predict.fun/remove-orders-by-hash-38139973e0
     * @param {string} id the order hash, as returned by createOrder
     * @param {string} [outcome] unified outcome handle the order belongs to
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CancelOrder(string id, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> orders = ccxt.BaseExchange.FromPredictionOrderList(await this.CancelOrders(new List<object>() {id},outcome, parameters));
        IDictionary<string, object> order = this.safeDict(orders, 0);
        if ((order == null))
        {
            throw new OrderNotFound (((this.id + " cancelOrder() could not remove ") + id)) ;
        }
        return ccxt.BaseExchange.ToPredictionOrder(order);
    }

    /**
     * @method
     * @name predictfun#cancelOrders
     * @description removes several of your own orders from the order book, up to a hundred at a time
     * @see https://dev.predict.fun/remove-orders-by-hash-38139973e0
     * @param {string[]} ids the order hashes, as returned by createOrder
     * @param {string} [outcome] unified outcome handle the orders belong to
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [order structures](https://docs.ccxt.com/#/?id=order-structure)
     */
    public async override Task<List<ccxt.PredictionOrder>> CancelOrders(object ids, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> outcomeObj = null;
        if ((outcome != null))
        {
            await this.loadOutcome(outcome);
            outcomeObj = this.outcome(outcome);
        }
        int idsLength = getArrayLength(ids);
        if ((idsLength == 0))
        {
            throw new ArgumentsRequired ((this.id + " cancelOrders() requires at least one order hash")) ;
        }
        if (idsLength > 100)
        {
            throw new BadRequest ((this.id + " cancelOrders() takes at most 100 order hashes per call")) ;
        }
        // the JWT identifies the signer whose orders may be pulled
        await this.authenticate();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "data", new Dictionary<string, object>() {
                { "hashes", ids },
            } },
        };
        // this only pulls the orders off the book, it does not cancel them on chain
        Dictionary<string, object> response = await this.predictfunPostV1OrdersRemoveByHash(this.extend(request, parameters));
        //
        //     {
        //         "removed": [ "0xebf11bdff189b8609c9ae66bebb20b94742865a2d94970856f3fb6b0896f9ec0" ],
        //         "rejected": [],
        //         "noop": [ "0x00de1b3b4d8647c371022c3b952c82d89298ed3746d4677e582ef9808bbdc6cf" ],
        //         "success": true
        //     }
        //
        List<object> rejected = this.safeList(response, "rejected", new List<object>() {});
        int rejectedLength = rejected.Count;
        if (rejectedLength > 0)
        {
            throw new OrderNotFound (((this.id + " cancelOrders() was refused for ") + this.json(rejected))) ;
        }
        // the venue reports hashes only, so each one becomes a row the shared order parser can
        // read: it takes the hash off orderHash and the status through parseOrderStatus
        List<object> removed = this.safeList(response, "removed", new List<object>() {});
        List<object> noop = this.safeList(response, "noop", new List<object>() {});
        List<object> rows = new List<object>() {};
        int removedLength = removed.Count;
        for (int i = 0; i < removedLength; i++)
        {
            rows.Add(this.extend(response, new Dictionary<string, object>() {
                { "orderHash", getValue(removed, i) },
                { "status", "CANCELLED" },
            }));
        }
        int noopLength = noop.Count;
        for (int i = 0; i < noopLength; i++)
        {
            // accepted, but nothing was resting to pull: the order had already filled, expired,
            // was never booked, or had been removed before - so the status is left unknown
            rows.Add(this.extend(response, new Dictionary<string, object>() {
                { "orderHash", getValue(noop, i) },
            }));
        }
        return ccxt.BaseExchange.ToPredictionOrderList(this.parsePredictionOrders(rows, outcomeObj));
    }

    /**
     * @method
     * @name predictfun#fetchOrder
     * @description fetches one of your own orders by its hash
     * @see https://dev.predict.fun/get-order-by-hash-25326901e0
     * @param {string} id the order hash
     * @param {string} [outcome] unified outcome handle the order belongs to, resolved from the order when omitted
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
     */
    public async virtual Task<ccxt.PredictionOrder> FetchOrder(string id, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        IDictionary<string, object> outcomeObj = null;
        if ((outcome != null))
        {
            await this.loadOutcome(outcome);
            outcomeObj = this.outcome(outcome);
        }
        // the JWT identifies the wallet whose orders can be read
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "hash", id },
        };
        Dictionary<string, object> response = await this.predictfunGetV1OrdersHash(this.extend(request, parameters));
        //
        //     {
        //         "data": {
        //             "amount": "10000000000000000000",
        //             "amountFilled": "0",
        //             "currency": "USDT",
        //             "id": "415537",
        //             "isNegRisk": false,
        //             "isYieldBearing": true,
        //             "marketId": 2004048,
        //             "order": {
        //             "expiration": 1788717567,
        //             "feeRateBps": "200",
        //             "hash": "0xd0933a7528d1f4d8f82861a097a8e44298806f072a76bc9ec9c423707c94dfe7",
        //             "maker": "0x78C7b44105eB616B48d4A4328D4Ded1c3B53AF31",
        //             "makerAmount": "5000000000000000000",
        //             "nonce": "0",
        //             "salt": "1788713967425",
        //             "side": 0,
        //             "signature": "0x019cfd569d6d678a5ba900d43d93dfd55b3ef98c38d5b9bd243ac356a1fbffaa351e417d534195aa43bf20f07c6b82c25e7c49591f7c74565c3b9fa75b298bbb1c",
        //             "signatureType": 0,
        //             "signer": "0x78C7b44105eB616B48d4A4328D4Ded1c3B53AF31",
        //             "taker": "0x0000000000000000000000000000000000000000",
        //             "takerAmount": "10000000000000000000",
        //             "tokenId": "21794117812663370870023674333212505719146120894214542748572818978538793884650"},
        //             "rewardEarningRate": 0,
        //             "status": "CANCELLED",
        //             "strategy": "LIMIT"
        //         },
        //         "success": true
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        return ccxt.BaseExchange.ToPredictionOrder(this.parsePredictionOrder(data, outcomeObj));
    }

    /**
     * @method
     * @name predictfun#fetchOpenOrders
     * @description fetches your own orders that are still resting on the book (only limit orders can be fetched)
     * @see https://dev.predict.fun/get-orders-25326902e0
     * @param {string} [outcome] unified outcome handle to filter by, all outcomes when omitted
     * @param {int} [since] not used by predictfun fetchOpenOrders, the venue returns no order timestamps
     * @param {int} [limit] the maximum number of orders to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.after] cursor from a previous response, the venue pages back from the newest order
     * @returns {object[]} a list of [order structures](https://docs.ccxt.com/#/?id=order-structure)
     */
    public async override Task<List<ccxt.PredictionOrder>> FetchOpenOrders(string outcome = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "status", "OPEN" },
        };
        return ccxt.BaseExchange.ToPredictionOrderList(await this.fetchOrdersHelper(outcome, since, limit, this.extend(request, parameters)));
    }

