    /**
     * @ignore
     * @method
     * @name predictfun#socketUrl
     * @description the socket endpoint carrying the api key the venue demands on the handshake
     * @returns {string} the url to connect to
     */
    public virtual object socketUrl()
    {
        object urls = (this.urls != null && ((IDictionary<string, object>)this.urls).ContainsKey("api") ? ((IDictionary<string, object>)this.urls)["api"] : null);
        string? bs = this.safeString(urls, "ws");
        if ((bs == null))
        {
            throw new NotSupported ((this.id + " does not have a sandbox websocket endpoint")) ;
        }
        if ((this.apiKey == null))
        {
            throw new AuthenticationError ((this.id + " requires an apiKey for all methods - the venue answers the socket handshake with a 401 without one")) ;
        }
        // the key rides in the query string rather than a header: a browser cannot set headers on
        // a websocket handshake, and the venue documents both forms
        return ((bs + "?apiKey=") + this.apiKey);
    }

    /**
     * @ignore
     * @method
     * @name predictfun#requestId
     * @description a monotonic id the venue echoes back so a subscription reply can be matched to its request
     * @returns {int} the next request id
     */
    public virtual Int64 requestId()
    {
        this.lockId();
        Int64? previous = this.safeInteger(this.options, "requestId", 0);
        Int64 next = this.sum(previous, 1);
        this.options["requestId"] = next;
        this.unlockId();
        return next;
    }

    /**
     * @ignore
     * @method
     * @name predictfun#outcomeForToken
     * @description resolves the outcome a row belongs to from its own token id, taking the caller's outcome only when it names that same token
     * @param {string} [tokenId] the on chain token id the row carries
     * @param {object} [market] the outcome the caller asked about
     * @returns {object} the outcome object, or a stub keyed by the token id when it is not cached
     */
    public virtual object outcomeForToken(object tokenId, object market = null)
    {
        // the list endpoints (orders, matches, positions) answer for the whole wallet rather than
        // for the outcome asked about, so the caller's outcome is only a hint. safeOutcome falls
        // back to it on any cache miss, which stamped the requested outcome onto rows from other
        // markets - and the outcome filter afterwards then kept them, as they now matched
        string? hintId = this.safeString(market, "outcomeId");
        if (((tokenId == null)) || (isEqual(hintId, tokenId)))
        {
            return this.safeOutcome(tokenId, market);
        }
        return this.safeOutcome(tokenId);
    }

    /**
     * @ignore
     * @method
     * @name predictfun#outcomesByMarketId
     * @description the cached outcomes that belong to one venue market id
     * @param {string} [marketId] the venue market id
     * @returns {object[]} the outcome objects
     */
    public virtual object outcomesByMarketId(object marketId)
    {
        List<object> result = new List<object>() {};
        object cached = this.outcomes;
        if (((marketId == null)) || ((cached == null)))
        {
            return result;
        }
        List<object> handles = new List<object>(((IDictionary<string,object>)cached).Keys);
        int handlesLength = handles.Count;
        for (int i = 0; i < handlesLength; i++)
        {
            object outcomeObj = getValue(cached, getValue(handles, i));
            IDictionary<string, object> info = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            if (isEqual(this.safeString(info, "marketId"), marketId))
            {
                result.Add(outcomeObj);
            }
        }
        return result;
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleOrderBook
     * @description turns a book message into the two complementary outcome books of its market
     * @param {Client} client the websocket client
     * @param {object} message the raw message
     */
    public virtual void handleOrderBook(WebSocketClient client, object message)
    {
        //
        //     {
        //         "type": "M",
        //         "topic": "predictOrderbook/2107",
        //         "data": {
        //             "asks": [
        //                 [ 0.029, 1478.08 ],
        //                 [ 0.03, 870.93 ]
        //             ],
        //             "bids": [
        //                 [ 0.02, 1386.724081632653 ],
        //                 [ 0.017, 2640.3371187742646 ]
        //             ],
        //             "lastOrderSettled": {
        //                 "id": "3172327577",
        //                 "kind": "LIMIT",
        //                 "marketId": 2107,
        //                 "outcome": "Yes",
        //                 "price": "0.02",
        //                 "side": "Bid"
        //             },
        //             "marketId": 2107,
        //             "orderCount": 62,
        //             "settlementsPending": {
        //                 "asks": [
        //                     [ 0.029, 0.14906 ]
        //                 ],
        //                 "bids": []
        //             },
        //             "updateTimestampMs": 1788953990223,
        //             "version": 1
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        string? marketId = this.safeString(data, "marketId");
        Int64? timestamp = this.safeInteger(data, "updateTimestampMs");
        IList<object> rawAsks = (IList<object>)(this.safeList(data, "asks", new List<object>() {}));
        IList<object> rawBids = (IList<object>)(this.safeList(data, "bids", new List<object>() {}));
        // every message carries the whole book - the venue publishes no deltas - and the levels
        // arrive already sorted, best first
        List<object> yesBids = new List<object>() {};
        List<object> yesAsks = new List<object>() {};
        List<object> noBids = new List<object>() {};
        List<object> noAsks = new List<object>() {};
        int bidsLength = (rawBids?.Count ?? 0);
        for (int i = 0; i < bidsLength; i++)
        {
            List<object> bid = this.safeList(rawBids, i);
            string? bidPrice = this.safeString(bid, 0);
            double? bidSize = this.parseNumber(this.safeString(bid, 1));
            yesBids.Add(new List<object> {this.parseNumber(bidPrice), bidSize});
            // a bid for yes at p is an offer of no at 1 - p
            noAsks.Add(new List<object> {this.parseNumber(Precise.stringSub("1", bidPrice)), bidSize});
        }
        int asksLength = (rawAsks?.Count ?? 0);
        for (int i = 0; i < asksLength; i++)
        {
            List<object> ask = this.safeList(rawAsks, i);
            string? askPrice = this.safeString(ask, 0);
            double? askSize = this.parseNumber(this.safeString(ask, 1));
            yesAsks.Add(new List<object> {this.parseNumber(askPrice), askSize});
            noBids.Add(new List<object> {this.parseNumber(Precise.stringSub("1", askPrice)), askSize});
        }
        object outcomes = this.outcomesByMarketId(marketId);
        int outcomesLength = getArrayLength(outcomes);
        for (int i = 0; i < outcomesLength; i++)
        {
            IDictionary<string, object> outcomeObj = this.safeDict(outcomes, i);
            IDictionary<string, object> outcomeInfo = this.safeDict(outcomeObj, "info", new Dictionary<string, object>() {});
            bool isYesOutcome = (this.safeInteger(outcomeInfo, "indexSet") == 1);
            string? outcomeHandle = this.safeString(outcomeObj, "outcome");
            if ((outcomeHandle != null))
            {
                if (!(((outcomeHandle != null) && ((IDictionary<string, object>)this.orderbooks).ContainsKey(outcomeHandle))))
                {
                    ((IDictionary<string,object>)this.orderbooks)[(string)outcomeHandle] = this.orderBook(new Dictionary<string, object>() {});
                }
                ccxt.pro.IOrderBook orderbook = this.getOrderBook(this.orderbooks, outcomeHandle);
                List<object> bids = yesBids;
                List<object> asks = yesAsks;
                if (!isYesOutcome)
                {
                    bids = this.sortBy(noBids, 0, true);
                    asks = this.sortBy(noAsks, 0);
                }
                (orderbook as IOrderBook).reset(new Dictionary<string, object>() {
                    { "bids", bids },
                    { "asks", asks },
                    { "timestamp", timestamp },
                    { "datetime", this.iso8601(timestamp) },
                    { "outcome", outcomeHandle },
                    { "outcomeId", this.safeString(outcomeObj, "outcomeId") },
                    { "market", this.safeString(outcomeObj, "market") },
                    { "nonce", this.safeInteger(data, "version") },
                });
                client.resolve(orderbook, ("orderbook::" + outcomeHandle));
            }
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleWalletEvent
     * @description turns one wallet event into the order it describes, and into a trade when it settled
     * @param {Client} client the websocket client
     * @param {object} message the raw message
     */
    public virtual void handleWalletEvent(WebSocketClient client, object message)
    {
        //
        //     {
        //         "type": "M",
        //         "topic": "predictWalletEvents/eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9...",
        //         "data": {
        //             "type": "orderTransactionSuccess",
        //             "orderId": "3420472350",
        //             "orderHash": "0x7d097327cc15754411b7ec3e3e074ff3e974394a75aa5c81fdf90b4e67e59c15",
        //             "settlementId": "01a08f55-d6f7-77e3-895e-81cf62d8aa09",
        //             "timestamp": 1789111162000,
        //             "walletAddress": "0xabababababababababababababababababababab",
        //             "isMaker": false,
        //             "fee": { "amountWei": "400000000000000", "type": "COLLATERAL" },
        //             "fill": {
        //                 "executedPriceWei": "20000000000000000",
        //                 "executedSizeWei": "1000000000000000000",
        //                 "executedValueWei": "20000000000000000"
        //             },
        //             "details": {
        //                 "categorySlug": "will-trump-acquire-greenland-before-2027",
        //                 "marketId": 2107,
        //                 "marketQuestion": "Will Trump acquire Greenland before 2027?",
        //                 "outcome": "YES",
        //                 "outcomeIndex": 1,
        //                 "outcomeName": "Yes",
        //                 "price": "0.010",
        //                 "quantity": "1.000",
        //                 "quantityFilled": "1.000",
        //                 "quoteType": "ASK",
        //                 "strategyType": "MARKET",
        //                 "value": "0.01",
        //                 "valueFilled": "0.01"
        //             }
        //         }
        //     }
        //
        // the details block is the same on every variant and is quoted in units, while fill and fee
        // are quoted in wei. observed live: orderAccepted, orderMarketMatchPlan (which the venue
        // sends but does not document), orderTransactionSubmitted, orderTransactionSuccess and
        // orderCancelled - the latter arrives with the same envelope and no fill
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        IDictionary<string, object> order = ((IDictionary<string, object>)this.parseWalletEventOrder(data));
        this.handleWalletEventOrder(client, order);
        // only a confirmed on-chain settlement is a trade: a submitted transaction has not landed
        // yet and a failed one never did, so neither belongs in myTrades
        string? eventType = this.safeString(data, "type");
        if (eventType == "orderTransactionSuccess")
        {
            this.handleWalletEventTrade(client, data, order);
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleWalletEventOrder
     * @description stores the order a wallet event describes and wakes whoever waits on it
     * @param {Client} client the websocket client
     * @param {object} order the parsed order
     */
    public virtual void handleWalletEventOrder(WebSocketClient client, object order)
    {
        if ((this.orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCacheByOutcomeById(limit);
        }
        ccxt.pro.ArrayCache stored = this.orders;
        stored.append(order);
        client.resolve(stored, "orders");
        string? outcomeHandle = this.safeString(order, "outcome");
        if ((outcomeHandle != null))
        {
            client.resolve(stored, ("orders::" + outcomeHandle));
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleWalletEventTrade
     * @description stores the settled fill a wallet event carries and wakes whoever waits on it
     * @param {Client} client the websocket client
     * @param {object} event the raw event
     * @param {object} order the order the same event was parsed into
     */
    public virtual void handleWalletEventTrade(WebSocketClient client, object eventVar, object order)
    {
        IDictionary<string, object> trade = ((IDictionary<string, object>)this.parseWalletEventTrade(eventVar, order));
        if ((this.myTrades == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            this.myTrades = new ArrayCacheByOutcomeById(limit);
        }
        ccxt.pro.ArrayCache stored = this.myTrades;
        stored.append(trade);
        client.resolve(stored, "myTrades");
        string? outcomeHandle = this.safeString(trade, "outcome");
        if ((outcomeHandle != null))
        {
            client.resolve(stored, ("myTrades::" + outcomeHandle));
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#walletEventOutcome
     * @description resolves the cached outcome a wallet event refers to, by market and outcome index
     * @param {object} details the event's details block
     * @returns {object} the outcome object, or a stub when the market is not cached
     */
    public virtual object walletEventOutcome(object details)
    {
        string? marketId = this.safeString(details, "marketId");
        Int64? outcomeIndex = this.safeInteger(details, "outcomeIndex");
        object outcomes = this.outcomesByMarketId(marketId);
        int outcomesLength = getArrayLength(outcomes);
        for (int i = 0; i < outcomesLength; i++)
        {
            object candidate = getValue(outcomes, i);
            IDictionary<string, object> info = this.safeDict(candidate, "info", new Dictionary<string, object>() {});
            if ((this.safeInteger(info, "indexSet") == outcomeIndex))
            {
                return candidate;
            }
        }
        // the wallet stream reports every market the wallet ever touched, including ones outside
        // the capped listing watchOrders () warms the cache from, so a miss survives that warm-up.
        // the event does name its topic and its outcome, and the unified event handle and label are
        // derived from exactly those two strings - so both are rebuilt here the way parseTopicMarket
        // builds them. the market symbol and the token id are not: the first needs the topic's
        // market count and the second the on-chain id, neither of which the event carries. they stay
        // undefined rather than guessed - a handle that does not match the one the rest of the api
        // reports is worse than none at all
        string? topicSlug = this.safeString(details, "categorySlug");
        string? eventHandle = null;
        if ((topicSlug != null))
        {
            eventHandle = this.shortenSlug(topicSlug);
        }
        string? label = ((string)this.stripPriceFormatting(this.safeStringUpper(details, "outcomeName")));
        return new Dictionary<string, object>() {
            { "outcome", null },
            { "outcomeId", null },
            { "market", null },
            { "label", label },
            { "event", eventHandle },
            { "info", details },
        };
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parseWalletEventOrder
     * @description parses a wallet event into the unified order it describes
     * @param {object} event the raw event
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public virtual object parseWalletEventOrder(object eventVar)
    {
        //
        //     {
        //         "type": "orderTransactionSuccess",
        //         "orderId": "3420472350",
        //         "orderHash": "0x7d097327cc15754411b7ec3e3e074ff3e974394a75aa5c81fdf90b4e67e59c15",
        //         "settlementId": "01a08f55-d6f7-77e3-895e-81cf62d8aa09",
        //         "timestamp": 1789111162000,
        //         "walletAddress": "0xabababababababababababababababababababab",
        //         "isMaker": false,
        //         "fee": { "amountWei": "400000000000000", "type": "COLLATERAL" },
        //         "fill": {
        //             "executedPriceWei": "20000000000000000",
        //             "executedSizeWei": "1000000000000000000",
        //             "executedValueWei": "20000000000000000"
        //         },
        //         "details": {
        //             "categorySlug": "will-trump-acquire-greenland-before-2027",
        //             "marketId": 2107,
        //             "marketQuestion": "Will Trump acquire Greenland before 2027?",
        //             "outcome": "YES",
        //             "outcomeIndex": 1,
        //             "outcomeName": "Yes",
        //             "price": "0.010",
        //             "quantity": "1.000",
        //             "quantityFilled": "1.000",
        //             "quoteType": "ASK",
        //             "strategyType": "MARKET",
        //             "value": "0.01",
        //             "valueFilled": "0.01"
        //         }
        //     }
        //
        IDictionary<string, object> details = this.safeDict(eventVar, "details", new Dictionary<string, object>() {});
        object outcomeObj = this.walletEventOutcome(details);
        string? eventType = this.safeString(eventVar, "type");
        string? amount = this.safeString(details, "quantity");
        string? filled = this.safeString(details, "quantityFilled");
        // every variant names a state of one order, so the event type is the status
        string? status = null;
        if ((eventType == "orderAccepted") || (eventType == "orderMarketMatchPlan") || (eventType == "orderTransactionSubmitted") || (eventType == "orderTransactionFailed"))
        {
            // orderMarketMatchPlan is not in the documented union but the venue does send it: the
            // order is accepted and being matched, which is the same state the caller sees as open
            status = "open";
        } else if (eventType == "orderNotAccepted")
        {
            status = "rejected";
        } else if (eventType == "orderExpired")
        {
            status = "expired";
        } else if (eventType == "orderCancelled")
        {
            status = "canceled";
        } else if (eventType == "orderTransactionSuccess")
        {
            // a settled fill closes the order only once nothing is left of it
            status = "open";
            if (((amount != null)) && ((filled != null)) && !Precise.stringLt(filled, amount))
            {
                status = "closed";
            }
        }
        string? quoteType = this.safeStringLower(details, "quoteType");
        string? side = null;
        if (quoteType == "bid")
        {
            side = "buy";
        } else if (quoteType == "ask")
        {
            side = "sell";
        }
        string? remaining = null;
        if (((amount != null)) && ((filled != null)))
        {
            remaining = Precise.stringSub(amount, filled);
        }
        Int64? timestamp = this.safeInteger(eventVar, "timestamp");
        return this.safePredictionOrder(new Dictionary<string, object>() {
            { "id", this.safeString2(eventVar, "orderHash", "orderId") },
            { "clientOrderId", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", timestamp },
            { "status", status },
            { "type", this.safeStringLower(details, "strategyType") },
            { "timeInForce", null },
            { "side", side },
            { "price", this.safeNumber(details, "price") },
            { "average", null },
            { "amount", this.parseNumber(amount) },
            { "filled", this.parseNumber(filled) },
            { "remaining", this.parseNumber(remaining) },
            { "cost", this.safeNumber(details, "valueFilled") },
            { "fee", null },
            { "reduceOnly", null },
            { "postOnly", null },
            { "trades", new List<object>() {} },
            { "outcome", this.safeOutcomeSymbol(null, outcomeObj) },
            { "outcomeId", this.safeString(outcomeObj, "outcomeId") },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "event", this.safeString(outcomeObj, "event") },
            { "info", eventVar },
        });
    }

    /**
     * @ignore
     * @method
     * @name predictfun#parseWalletEventTrade
     * @description parses the settled fill a wallet event carries
     * @param {object} event the raw event
     * @param {object} order the order the same event was parsed into
     * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public virtual object parseWalletEventTrade(object eventVar, object order)
    {
        IDictionary<string, object> fill = this.safeDict(eventVar, "fill", new Dictionary<string, object>() {});
        // the fill is quoted in wei while the details block is quoted in units, so only these three
        // fields are scaled down
        string? price = Precise.stringDiv(this.safeString(fill, "executedPriceWei"), "1000000000000000000");
        string? amount = Precise.stringDiv(this.safeString(fill, "executedSizeWei"), "1000000000000000000");
        string? cost = Precise.stringDiv(this.safeString(fill, "executedValueWei"), "1000000000000000000");
        bool? isMaker = this.safeBool(eventVar, "isMaker");
        string? takerOrMaker = null;
        if ((isMaker != null))
        {
            takerOrMaker = isMaker == true ? "maker" : "taker";
        }
        IDictionary<string, object> rawFee = this.safeDict(eventVar, "fee");
        Dictionary<string, object> fee = null;
        if ((rawFee != null))
        {
            string? feeType = this.safeString(rawFee, "type");
            fee = new Dictionary<string, object>() {
                { "currency", (feeType == "COLLATERAL") ? "USDT" : null },
                { "cost", this.parseNumber(Precise.stringDiv(this.safeString(rawFee, "amountWei"), "1000000000000000000")) },
            };
        }
        Int64? timestamp = this.safeInteger(eventVar, "timestamp");
        return this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", this.safeString(eventVar, "settlementId") },
            { "order", this.safeString(eventVar, "orderHash") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "outcome", this.safeString(order, "outcome") },
            { "outcomeId", this.safeString(order, "outcomeId") },
            { "label", this.safeString(order, "label") },
            { "market", this.safeString(order, "market") },
            { "type", this.safeString(order, "type") },
            { "side", this.safeString(order, "side") },
            { "takerOrMaker", takerOrMaker },
            { "price", this.parseNumber(price) },
            { "amount", this.parseNumber(amount) },
            { "cost", this.parseNumber(cost) },
            { "fee", fee },
            { "info", eventVar },
        });
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleHeartbeat
     * @description echoes the probe timestamp back, which is what keeps the connection open
     * @param {Client} client the websocket client
     * @param {object} message the raw message
     */
    public virtual void handleHeartbeat(WebSocketClient client, object message)
    {
        // client.send () is a coroutine in the python port, so firing it from this synchronous
        // handler would drop it unsent and the venue would close the socket on its next probe
        this.spawn(this.pong, new object[] { client, message});
    }

    /**
     * @ignore
     * @method
     * @name predictfun#pong
     * @description echoes the probe timestamp back, which is what keeps the connection open
     * @param {Client} client the websocket client
     * @param {object} message the raw probe
     */
    public async virtual Task pong(WebSocketClient client, Dictionary<string, object> message)
    {
        // the server probes every fifteen seconds and drops the connection on the next probe unless
        // the exact timestamp it sent comes back, so the reply echoes it verbatim
        Dictionary<string, object> reply = new Dictionary<string, object>() {
            { "method", "heartbeat" },
            { "data", this.safeInteger(message, "data") },
        };
        try
        {
            await client.send(reply);
        } catch(Exception e)
        {
            var error = new NetworkError(((this.id + " pong failed - ") + (this.exceptionMessage(e))));
            client.reset(error);
        }
    }

    /**
     * @ignore
     * @method
     * @name predictfun#handleMessage
     * @description routes a socket message to the handler of its topic
     * @param {Client} client the websocket client
     * @param {object} message the raw message
     */
    public override void handleMessage(WebSocketClient client, object message)
    {
        string? messageType = this.safeString(message, "type");
        if (messageType == "R")
        {
            // a subscription reply - the venue reports a rejected topic here instead of closing.
            // it carries only the request id, so the subscription that request registered is found
            // by it - see handleSubscriptionStatus in pro/binance.ts
            string? id = this.safeString(message, "requestId");
            Dictionary<string, object> subscriptionsById = this.indexBy(client.subscriptions, "id");
            IDictionary<string, object> subscription = this.safeDict(subscriptionsById, id, new Dictionary<string, object>() {});
            bool? success = this.safeBool(message, "success", false);
            if (success != true)
            {
                this.handleSubscriptionError(client, message, subscription);
                return;
            }
            if ((this.safeBool(subscription, "unsubscribe", false) == true))
            {
                this.handleUnSubscription(client, subscription);
            }
            return;
        }
        string? topic = this.safeString(message, "topic");
        if (topic == "heartbeat")
        {
            this.handleHeartbeat(client, message);
            return;
        }
        if ((topic == null))
        {
            return;
        }
        List<object> parts = topic.Split(new [] {"/"}, StringSplitOptions.None).ToList<object>();
        string? channel = this.safeString(parts, 0);
        if (channel == "predictOrderbook")
        {
            this.handleOrderBook(client, message);
        } else if (channel == "predictWalletEvents")
        {
            this.handleWalletEvent(client, message);
        }
    }

    public override Int64 nonce()
    {
        // the order salt is a millisecond timestamp; incrementingNonce () reads this and keeps salts
        // unique when two identical orders are signed within the same millisecond
        return this.milliseconds();
    }

    /**
     * @ignore
     * @method
     * @name predictfun#sign
     * @description builds the request URL and attaches the API key header required by every endpoint
     * @param {string} path the endpoint path
     * @param {string|string[]} [api] the API group and access level
     * @param {string} [method] HTTP method
     * @param {object} [params] request parameters
     * @param {object} [headers] request headers
     * @param {object} [body] request body
     * @returns {object} a dictionary with url, method, body and headers
     */
    public override Dictionary<string, object> sign(object path, object api = null, object method = null, object parameters = null, object headers = null, object body = null)
    {
        // the venue authenticates every endpoint, so the key is required up front rather than
        // per access level - a key-less request is answered with a 401 by the API gateway.
        // the testnet is the exception, it is served without an API key at all
        api ??= "predictfun";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        bool? sandboxMode = this.safeBool(this.options, "sandboxMode", false);
        string? apiKey = this.apiKey;
        if (((apiKey == null)) && sandboxMode != true)
        {
            throw new AuthenticationError ((this.id + " sign() requires the \"apiKey\" credential for all endpoints")) ;
        }
        object apiGroup = (api is string) ? api : getValue(api, 0);
        object baseUrls = (this.urls != null && ((IDictionary<string, object>)this.urls).ContainsKey("api") ? ((IDictionary<string, object>)this.urls)["api"] : null);
        string baseUrl = this.safeString(baseUrls, apiGroup, ((string)getValue(baseUrls, "predictfun")));
        string url = ((baseUrl + "/") + this.implodeParams(path, parameters));
        object query = this.omit(parameters, this.extractParams(path));
        if (isEqual(method, "GET"))
        {
            if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
            {
                url = url + ("?" + this.urlencode(query));
            }
        }
        object existingHeaders = ((headers != null)) ? headers : new Dictionary<string, object>() {};
        headers = existingHeaders;
        Dictionary<string, object> authHeaders = new Dictionary<string, object>() {};
        if (((apiKey != null)) && (sandboxMode != true))
        {
            // the php transpiler prefixes every standalone 'api' with a $, string literals included,
            // since sign () has a parameter of that name - ending the literal right after it avoids that
            string apiKeyHeader = ("x-api" + "-key");
            authHeaders[(string)apiKeyHeader] = apiKey;
        }
        // the API key authorises the request, the JWT authorises acting for a wallet - authenticate ()
        // caches it, so it is attached to every call once an order action has asked for one
        // the JWT is scoped to one wallet, so it only goes to the endpoints that act for a wallet.
        // attaching it to public reads would hand the venue a wallet credential they do not need.
        // note v1/positions/{address} reads someone else's positions and is deliberately absent,
        // as is v1/orders/matches, which is the public trade feed
        List<object> walletPaths = new List<object>() {"v1/orders", "v1/orders/{hash}", "v1/orders/remove", "v1/orders/remove-by-hash", "v1/account", "v1/account/activity", "v1/account/referral", "v1/positions", "v1/oauth/finalize", "v1/oauth/orders", "v1/oauth/orders/create", "v1/oauth/orders/cancel", "v1/oauth/positions"};
        string? jwtToken = this.safeString(this.options, "jwtToken");
        // unlike the API key, the JWT IS required on the testnet - wallet endpoints there answer
        // 401 without it, so it is attached on both hosts
        if (((jwtToken != null)) && this.inArray(path, walletPaths))
        {
            authHeaders["Authorization"] = ("Bearer " + jwtToken);
        }
        if (!isEqual(method, "GET"))
        {
            if (sandboxMode != true)
            {
                this.checkRequiredCredentials();
            }
            authHeaders["Content-Type"] = "application/json";
            body = this.json(parameters);
        }
        headers = this.extend(headers, authHeaders);
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }
}
